<?php requireRole('parent'); ?><section class="hero"><h1>👨‍👩‍👧 Parent Dashboard</h1><p>Track your child's progress.</p></section><div class="card"><h2>Link a student</h2><p>Ask the student for the CodeBridge link code shown in their profile.</p><form id="link"><input name="link_code" placeholder="Student link code" required><input type="hidden" name="action" value="link"><input type="hidden" name="csrf" value="<?=h(csrfToken())?>"><button class="btn">Link Student</button></form><div id="m"></div></div><br><div id="children" class="grid"></div><script>async function load(){let d=await api('backend/api/parent.php');document.getElementById('children').innerHTML=d.children.length?d.children.map(c=>`<div class="card"><h2>${escapeHTML(c.full_name)}</h2><p>⭐ ${c.xp} XP &nbsp; 🏆 Level ${c.level} &nbsp; 🔥 ${c.streak}</p>${c.courses.map(x=>`<p>${escapeHTML(x.title_en)} — ${x.percent_complete}%</p><div class="progress"><div style="width:${x.percent_complete}%"></div></div>`).join('')}</div>`).join(''):'<div class="card"><h2>No linked students yet.</h2></div>'}document.getElementById('link').onsubmit=async e=>{e.preventDefault();try{await post('backend/api/parent.php',new FormData(e.target));load()}catch(x){document.getElementById('m').innerHTML='<div class="notice error">'+escapeHTML(x.message)+'</div>'}};load()</script>
